<script setup lang="ts">definePageMeta({layout:"admin",middleware:"admin"});const{data,refresh}=await useFetch("/api/admin/vouchers");const form=reactive({code:"",kind:"fixed",value:10000,minimumOrder:0,maxDiscount:null as number|null,usageLimit:null as number|null,startsAt:null,expiresAt:null});const error=ref("");async function create(){error.value="";try{await $fetch("/api/admin/vouchers",{method:"POST",body:form});form.code="";await refresh();}catch(cause:any){error.value=cause?.data?.statusMessage||"Voucher gagal dibuat.";}}useSeoMeta({title:"Admin Voucher"});</script>
<template><div><AdminPageHeader title="Voucher"/><div class="grid gap-6 xl:grid-cols-[380px_1fr]"><form class="surface grid gap-4 p-5" @submit.prevent="create"><label class="field-label">Kode<input v-model="form.code" class="field" required></label><label class="field-label">Jenis<select v-model="form.kind" class="field"><option value="fixed">Nominal</option><option value="percentage">Persentase</option></select></label><label class="field-label">Nilai<input v-model.number="form.value" type="number" class="field" required></label><label class="field-label">Minimum order<input v-model.number="form.minimumOrder" type="number" class="field"></label><label class="field-label">Batas penggunaan<input v-model.number="form.usageLimit" type="number" class="field"></label><p v-if="error" class="text-sm text-red-600">{{error}}</p><AppButton type="submit">Buat voucher</AppButton></form><div class="surface overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-slate-50"><tr><th class="p-4">Kode</th><th class="p-4">Jenis</th><th class="p-4">Nilai</th><th class="p-4">Pemakaian</th></tr></thead><tbody><tr v-for="voucher in data?.vouchers" :key="(voucher as any).id" class="border-t"><td class="p-4 font-black">{{(voucher as any).code}}</td><td class="p-4">{{(voucher as any).kind}}</td><td class="p-4">{{(voucher as any).value}}</td><td class="p-4">{{(voucher as any).used_count}} / {{(voucher as any).usage_limit||'∞'}}</td></tr></tbody></table></div></div></div></template>
